/* ImportOpsDB V1 - SQL Server 2019+ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF DB_ID(N'ImportOpsDB') IS NULL CREATE DATABASE ImportOpsDB;
GO
USE ImportOpsDB;
GO
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='cfg') EXEC('CREATE SCHEMA cfg');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='sec') EXEC('CREATE SCHEMA sec');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='crm') EXEC('CREATE SCHEMA crm');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='sales') EXEC('CREATE SCHEMA sales');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='ops') EXEC('CREATE SCHEMA ops');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='doc') EXEC('CREATE SCHEMA doc');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='fin') EXEC('CREATE SCHEMA fin');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='audit') EXEC('CREATE SCHEMA audit');
GO

CREATE TABLE cfg.COMPANY(
 company_id BIGINT IDENTITY PRIMARY KEY, legal_name NVARCHAR(200) NOT NULL, trade_name NVARCHAR(200) NULL,
 tax_id NVARCHAR(30) NOT NULL, country_code CHAR(2) NOT NULL DEFAULT 'PE', base_currency_code CHAR(3) NOT NULL DEFAULT 'PEN',
 email NVARCHAR(200) NULL, phone NVARCHAR(50) NULL, address_line NVARCHAR(300) NULL, is_active BIT NOT NULL DEFAULT 1,
 created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(), created_by BIGINT NULL, modified_at DATETIME2(0) NULL,
 modified_by BIGINT NULL, is_deleted BIT NOT NULL DEFAULT 0, row_ver ROWVERSION, CONSTRAINT UQ_COMPANY_TAX UNIQUE(tax_id)
);
CREATE TABLE cfg.CURRENCY(currency_code CHAR(3) PRIMARY KEY,currency_name NVARCHAR(80) NOT NULL,symbol NVARCHAR(10),decimal_places TINYINT NOT NULL DEFAULT 2,is_active BIT NOT NULL DEFAULT 1);
CREATE TABLE cfg.COUNTRY(country_code CHAR(2) PRIMARY KEY,country_name NVARCHAR(120) NOT NULL,iso3_code CHAR(3),is_active BIT NOT NULL DEFAULT 1);
CREATE TABLE cfg.PORT(port_id BIGINT IDENTITY PRIMARY KEY,country_code CHAR(2) NOT NULL,port_code NVARCHAR(20),port_name NVARCHAR(160) NOT NULL,city_name NVARCHAR(120),port_type VARCHAR(20) NOT NULL,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_PORT_COUNTRY FOREIGN KEY(country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT CK_PORT_TYPE CHECK(port_type IN('SEA','AIR','LAND','OTHER')));
CREATE TABLE cfg.TRANSPORT_MODE(transport_mode_id INT IDENTITY PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name NVARCHAR(80) NOT NULL,is_active BIT NOT NULL DEFAULT 1);
CREATE TABLE cfg.INCOTERM(incoterm_code VARCHAR(10) PRIMARY KEY,description NVARCHAR(200) NOT NULL,is_active BIT NOT NULL DEFAULT 1);
CREATE TABLE cfg.PAYMENT_METHOD(payment_method_id INT IDENTITY PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name NVARCHAR(100) NOT NULL,is_active BIT NOT NULL DEFAULT 1);
CREATE TABLE cfg.DOCUMENT_TYPE(document_type_id INT IDENTITY PRIMARY KEY,company_id BIGINT NULL,code VARCHAR(40) NOT NULL,name NVARCHAR(120) NOT NULL,category VARCHAR(30) NOT NULL,is_required_default BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_DOCTYPE_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT CK_DOCTYPE_CAT CHECK(category IN('COMMERCIAL','LOGISTICS','CUSTOMS','FINANCIAL','OTHER')));
CREATE UNIQUE INDEX UX_DOCTYPE_COMPANY_CODE ON cfg.DOCUMENT_TYPE(company_id,code);
CREATE TABLE cfg.EXPENSE_CATEGORY(expense_category_id INT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,code VARCHAR(40) NOT NULL,name NVARCHAR(120) NOT NULL,is_rebillable_default BIT NOT NULL DEFAULT 1,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_EXPCAT_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT UQ_EXPCAT UNIQUE(company_id,code));
CREATE TABLE cfg.SERVICE_CATEGORY(service_category_id INT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,code VARCHAR(40) NOT NULL,name NVARCHAR(120) NOT NULL,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_SRVCAT_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT UQ_SRVCAT UNIQUE(company_id,code));
CREATE TABLE cfg.WORKFLOW_STAGE(workflow_stage_id INT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,code VARCHAR(40) NOT NULL,name NVARCHAR(120) NOT NULL,display_order INT NOT NULL,is_final BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_STAGE_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT UQ_STAGE UNIQUE(company_id,code));
CREATE TABLE cfg.WORKFLOW_TRANSITION(workflow_transition_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,from_stage_id INT NOT NULL,to_stage_id INT NOT NULL,requires_comment BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_TRANS_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_TRANS_FROM FOREIGN KEY(from_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_TRANS_TO FOREIGN KEY(to_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT UQ_TRANS UNIQUE(company_id,from_stage_id,to_stage_id),CONSTRAINT CK_TRANS_DIFF CHECK(from_stage_id<>to_stage_id));
CREATE TABLE cfg.STAGE_TASK_TEMPLATE(stage_task_template_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,workflow_stage_id INT NOT NULL,title NVARCHAR(180) NOT NULL,description NVARCHAR(500),is_mandatory BIT NOT NULL DEFAULT 0,due_days_offset INT,display_order INT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_TASKTPL_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_TASKTPL_STAGE FOREIGN KEY(workflow_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id));
CREATE TABLE cfg.STAGE_DOCUMENT_REQUIREMENT(stage_document_requirement_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,workflow_stage_id INT NOT NULL,document_type_id INT NOT NULL,is_mandatory BIT NOT NULL DEFAULT 1,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_STGDOC_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_STGDOC_STAGE FOREIGN KEY(workflow_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_STGDOC_TYPE FOREIGN KEY(document_type_id) REFERENCES cfg.DOCUMENT_TYPE(document_type_id),CONSTRAINT UQ_STGDOC UNIQUE(company_id,workflow_stage_id,document_type_id));
GO

CREATE TABLE sec.APP_USER(user_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,external_auth_id NVARCHAR(100),username NVARCHAR(100) NOT NULL,email NVARCHAR(200),first_name NVARCHAR(100),last_name NVARCHAR(100),phone NVARCHAR(50),is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_USER_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id));
CREATE UNIQUE INDEX UX_USER_COMPANY_USERNAME ON sec.APP_USER(company_id,username) WHERE is_deleted=0;
CREATE UNIQUE INDEX UX_USER_EXTERNAL ON sec.APP_USER(external_auth_id) WHERE external_auth_id IS NOT NULL;
CREATE TABLE sec.ROLE(role_id INT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,code VARCHAR(40) NOT NULL,name NVARCHAR(100) NOT NULL,is_system BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_ROLE_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT UQ_ROLE UNIQUE(company_id,code));
CREATE TABLE sec.USER_ROLE(user_id BIGINT NOT NULL,role_id INT NOT NULL,assigned_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),assigned_by BIGINT NULL,PRIMARY KEY(user_id,role_id),
 CONSTRAINT FK_UR_USER FOREIGN KEY(user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_UR_ROLE FOREIGN KEY(role_id) REFERENCES sec.ROLE(role_id));
GO

CREATE TABLE crm.CLIENT(client_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,client_type VARCHAR(20) NOT NULL DEFAULT 'COMPANY',legal_name NVARCHAR(200) NOT NULL,trade_name NVARCHAR(200),tax_id NVARCHAR(30),country_code CHAR(2) NOT NULL DEFAULT 'PE',email NVARCHAR(200),phone NVARCHAR(50),credit_days INT,preferred_currency_code CHAR(3),notes NVARCHAR(1000),account_manager_user_id BIGINT,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_CLIENT_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_CLIENT_COUNTRY FOREIGN KEY(country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT FK_CLIENT_CURR FOREIGN KEY(preferred_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_CLIENT_MGR FOREIGN KEY(account_manager_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_CLIENT_TYPE CHECK(client_type IN('COMPANY','PERSON')));
CREATE UNIQUE INDEX UX_CLIENT_TAX ON crm.CLIENT(company_id,tax_id) WHERE tax_id IS NOT NULL AND is_deleted=0;
CREATE INDEX IX_CLIENT_NAME ON crm.CLIENT(company_id,legal_name) INCLUDE(tax_id,is_active);
CREATE TABLE crm.CLIENT_CONTACT(client_contact_id BIGINT IDENTITY PRIMARY KEY,client_id BIGINT NOT NULL,full_name NVARCHAR(160) NOT NULL,position_name NVARCHAR(120),email NVARCHAR(200),phone NVARCHAR(50),mobile NVARCHAR(50),is_primary BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_CCONTACT_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id));
CREATE TABLE crm.CLIENT_ADDRESS(client_address_id BIGINT IDENTITY PRIMARY KEY,client_id BIGINT NOT NULL,address_type VARCHAR(20) NOT NULL DEFAULT 'LEGAL',address_line NVARCHAR(300) NOT NULL,district NVARCHAR(120),province NVARCHAR(120),department NVARCHAR(120),country_code CHAR(2) NOT NULL DEFAULT 'PE',is_primary BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,
 CONSTRAINT FK_CADDR_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_CADDR_COUNTRY FOREIGN KEY(country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT CK_CADDR_TYPE CHECK(address_type IN('LEGAL','BILLING','DELIVERY','OTHER')));
CREATE TABLE crm.SUPPLIER(supplier_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,legal_name NVARCHAR(200) NOT NULL,tax_id NVARCHAR(50),country_code CHAR(2),email NVARCHAR(200),phone NVARCHAR(50),address_line NVARCHAR(300),notes NVARCHAR(1000),is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_SUP_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_SUP_COUNTRY FOREIGN KEY(country_code) REFERENCES cfg.COUNTRY(country_code));
CREATE TABLE crm.SUPPLIER_CONTACT(supplier_contact_id BIGINT IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL,full_name NVARCHAR(160) NOT NULL,email NVARCHAR(200),phone NVARCHAR(50),position_name NVARCHAR(120),is_primary BIT NOT NULL DEFAULT 0,is_active BIT NOT NULL DEFAULT 1,CONSTRAINT FK_SCONTACT_SUP FOREIGN KEY(supplier_id) REFERENCES crm.SUPPLIER(supplier_id));
GO

CREATE SEQUENCE sales.SEQ_REQUEST_NO AS BIGINT START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE sales.SEQ_QUOTATION_NO AS BIGINT START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE ops.SEQ_OPERATION_NO AS BIGINT START WITH 1 INCREMENT BY 1;
GO

CREATE TABLE sales.IMPORT_REQUEST(request_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,request_no NVARCHAR(30) NOT NULL,client_id BIGINT NOT NULL,client_contact_id BIGINT NULL,supplier_id BIGINT NULL,requested_by_user_id BIGINT NOT NULL,assigned_user_id BIGINT NULL,request_date DATE NOT NULL DEFAULT CONVERT(date,GETDATE()),status VARCHAR(20) NOT NULL DEFAULT 'NEW',transport_mode_id INT NULL,incoterm_code VARCHAR(10) NULL,origin_country_code CHAR(2),destination_country_code CHAR(2),origin_port_id BIGINT,destination_port_id BIGINT,merchandise_description NVARCHAR(1000) NOT NULL,package_count DECIMAL(18,3),gross_weight_kg DECIMAL(18,3),volume_m3 DECIMAL(18,4),declared_value DECIMAL(19,4),declared_currency_code CHAR(3),desired_service_date DATE,customer_notes NVARCHAR(2000),internal_notes NVARCHAR(2000),rejection_reason NVARCHAR(1000),approved_at DATETIME2(0),approved_by_user_id BIGINT,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_REQ_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_REQ_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_REQ_CONTACT FOREIGN KEY(client_contact_id) REFERENCES crm.CLIENT_CONTACT(client_contact_id),CONSTRAINT FK_REQ_SUP FOREIGN KEY(supplier_id) REFERENCES crm.SUPPLIER(supplier_id),CONSTRAINT FK_REQ_REQBY FOREIGN KEY(requested_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_REQ_ASSIGN FOREIGN KEY(assigned_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_REQ_APPROVEDBY FOREIGN KEY(approved_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_REQ_TRANSPORT FOREIGN KEY(transport_mode_id) REFERENCES cfg.TRANSPORT_MODE(transport_mode_id),CONSTRAINT FK_REQ_INCOTERM FOREIGN KEY(incoterm_code) REFERENCES cfg.INCOTERM(incoterm_code),CONSTRAINT FK_REQ_ORICOUNTRY FOREIGN KEY(origin_country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT FK_REQ_DESTCOUNTRY FOREIGN KEY(destination_country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT FK_REQ_ORIPORT FOREIGN KEY(origin_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT FK_REQ_DESTPORT FOREIGN KEY(destination_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT FK_REQ_CURR FOREIGN KEY(declared_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT UQ_REQ_NO UNIQUE(company_id,request_no),CONSTRAINT CK_REQ_STATUS CHECK(status IN('NEW','UNDER_REVIEW','OBSERVED','QUOTED','APPROVED','REJECTED','CANCELLED')));
CREATE INDEX IX_REQ_STATUS_DATE ON sales.IMPORT_REQUEST(company_id,status,request_date DESC) INCLUDE(client_id,assigned_user_id);
CREATE TABLE sales.REQUEST_STATUS_HISTORY(request_status_history_id BIGINT IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL,old_status VARCHAR(20),new_status VARCHAR(20) NOT NULL,comment NVARCHAR(1000),changed_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),changed_by BIGINT NOT NULL,CONSTRAINT FK_REQH_REQ FOREIGN KEY(request_id) REFERENCES sales.IMPORT_REQUEST(request_id),CONSTRAINT FK_REQH_USER FOREIGN KEY(changed_by) REFERENCES sec.APP_USER(user_id));

CREATE TABLE sales.QUOTATION(quotation_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,quotation_no NVARCHAR(30) NOT NULL,request_id BIGINT NOT NULL,client_id BIGINT NOT NULL,version_no INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',currency_code CHAR(3) NOT NULL,issue_date DATE NOT NULL DEFAULT CONVERT(date,GETDATE()),valid_until DATE,subtotal DECIMAL(19,4) NOT NULL DEFAULT 0,discount_amount DECIMAL(19,4) NOT NULL DEFAULT 0,tax_amount DECIMAL(19,4) NOT NULL DEFAULT 0,total_amount DECIMAL(19,4) NOT NULL DEFAULT 0,terms NVARCHAR(2000),internal_notes NVARCHAR(2000),sent_at DATETIME2(0),approved_at DATETIME2(0),approved_by_name NVARCHAR(160),rejected_at DATETIME2(0),rejection_reason NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_QUO_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_QUO_REQ FOREIGN KEY(request_id) REFERENCES sales.IMPORT_REQUEST(request_id),CONSTRAINT FK_QUO_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_QUO_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT UQ_QUO_NO UNIQUE(company_id,quotation_no),CONSTRAINT UQ_QUO_VERSION UNIQUE(request_id,version_no),CONSTRAINT CK_QUO_STATUS CHECK(status IN('DRAFT','SENT','APPROVED','REJECTED','EXPIRED','CANCELLED')));
CREATE TABLE sales.QUOTATION_ITEM(quotation_item_id BIGINT IDENTITY PRIMARY KEY,quotation_id BIGINT NOT NULL,line_no INT NOT NULL,item_type VARCHAR(20) NOT NULL,description NVARCHAR(500) NOT NULL,quantity DECIMAL(18,4) NOT NULL DEFAULT 1,unit_price DECIMAL(19,4) NOT NULL,discount_amount DECIMAL(19,4) NOT NULL DEFAULT 0,tax_amount DECIMAL(19,4) NOT NULL DEFAULT 0,line_total DECIMAL(19,4) NOT NULL,expense_category_id INT,service_category_id INT,is_rebillable BIT NOT NULL DEFAULT 0,notes NVARCHAR(500),CONSTRAINT FK_QITEM_QUO FOREIGN KEY(quotation_id) REFERENCES sales.QUOTATION(quotation_id),CONSTRAINT FK_QITEM_EXP FOREIGN KEY(expense_category_id) REFERENCES cfg.EXPENSE_CATEGORY(expense_category_id),CONSTRAINT FK_QITEM_SRV FOREIGN KEY(service_category_id) REFERENCES cfg.SERVICE_CATEGORY(service_category_id),CONSTRAINT UQ_QITEM_LINE UNIQUE(quotation_id,line_no),CONSTRAINT CK_QITEM_TYPE CHECK(item_type IN('SERVICE','ESTIMATED_COST','OTHER')),CONSTRAINT CK_QITEM_QTY CHECK(quantity>0));
CREATE TABLE sales.QUOTATION_STATUS_HISTORY(quotation_status_history_id BIGINT IDENTITY PRIMARY KEY,quotation_id BIGINT NOT NULL,old_status VARCHAR(20),new_status VARCHAR(20) NOT NULL,comment NVARCHAR(1000),changed_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),changed_by BIGINT NOT NULL,CONSTRAINT FK_QH_QUO FOREIGN KEY(quotation_id) REFERENCES sales.QUOTATION(quotation_id),CONSTRAINT FK_QH_USER FOREIGN KEY(changed_by) REFERENCES sec.APP_USER(user_id));
GO

CREATE TABLE ops.IMPORT_OPERATION(operation_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_no NVARCHAR(30) NOT NULL,request_id BIGINT NULL,quotation_id BIGINT NULL,client_id BIGINT NOT NULL,client_contact_id BIGINT NULL,supplier_id BIGINT NULL,responsible_user_id BIGINT NOT NULL,current_stage_id INT NOT NULL,operational_status VARCHAR(30) NOT NULL DEFAULT 'OPEN',documentary_status VARCHAR(30) NOT NULL DEFAULT 'PENDING',financial_status VARCHAR(30) NOT NULL DEFAULT 'NO_MOVEMENTS',transport_mode_id INT,incoterm_code VARCHAR(10),origin_country_code CHAR(2),destination_country_code CHAR(2),origin_port_id BIGINT,destination_port_id BIGINT,merchandise_description NVARCHAR(1500) NOT NULL,package_count DECIMAL(18,3),gross_weight_kg DECIMAL(18,3),net_weight_kg DECIMAL(18,3),volume_m3 DECIMAL(18,4),declared_value DECIMAL(19,4),declared_currency_code CHAR(3),opened_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),estimated_close_date DATE,actual_close_date DATE,closed_at DATETIME2(0),closed_by_user_id BIGINT,cancellation_reason NVARCHAR(1000),notes NVARCHAR(2000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_OP_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_OP_REQ FOREIGN KEY(request_id) REFERENCES sales.IMPORT_REQUEST(request_id),CONSTRAINT FK_OP_QUO FOREIGN KEY(quotation_id) REFERENCES sales.QUOTATION(quotation_id),CONSTRAINT FK_OP_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_OP_CONTACT FOREIGN KEY(client_contact_id) REFERENCES crm.CLIENT_CONTACT(client_contact_id),CONSTRAINT FK_OP_SUP FOREIGN KEY(supplier_id) REFERENCES crm.SUPPLIER(supplier_id),CONSTRAINT FK_OP_RESP FOREIGN KEY(responsible_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_OP_STAGE FOREIGN KEY(current_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_OP_TRANS FOREIGN KEY(transport_mode_id) REFERENCES cfg.TRANSPORT_MODE(transport_mode_id),CONSTRAINT FK_OP_INCOTERM FOREIGN KEY(incoterm_code) REFERENCES cfg.INCOTERM(incoterm_code),CONSTRAINT FK_OP_OC FOREIGN KEY(origin_country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT FK_OP_DC FOREIGN KEY(destination_country_code) REFERENCES cfg.COUNTRY(country_code),CONSTRAINT FK_OP_OPORT FOREIGN KEY(origin_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT FK_OP_DPORT FOREIGN KEY(destination_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT FK_OP_CURR FOREIGN KEY(declared_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_OP_CLOSEBY FOREIGN KEY(closed_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT UQ_OP_NO UNIQUE(company_id,operation_no),CONSTRAINT CK_OP_OPER CHECK(operational_status IN('OPEN','ON_HOLD','IN_PROGRESS','DELIVERED','CANCELLED','CLOSED')),CONSTRAINT CK_OP_DOC CHECK(documentary_status IN('PENDING','OBSERVED','COMPLETE')),CONSTRAINT CK_OP_FIN CHECK(financial_status IN('NO_MOVEMENTS','FUNDED','IN_EXECUTION','PENDING_COLLECTION','PENDING_SETTLEMENT','PENDING_REFUND','CLOSED')));
CREATE INDEX IX_OP_STAGE ON ops.IMPORT_OPERATION(company_id,current_stage_id,operational_status) INCLUDE(client_id,responsible_user_id,opened_at);
CREATE INDEX IX_OP_CLIENT ON ops.IMPORT_OPERATION(client_id,opened_at DESC) INCLUDE(operation_no,operational_status,financial_status);
CREATE TABLE ops.OPERATION_STAGE_HISTORY(operation_stage_history_id BIGINT IDENTITY PRIMARY KEY,operation_id BIGINT NOT NULL,from_stage_id INT,to_stage_id INT NOT NULL,comment NVARCHAR(1000),changed_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),changed_by BIGINT NOT NULL,CONSTRAINT FK_OSH_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_OSH_FROM FOREIGN KEY(from_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_OSH_TO FOREIGN KEY(to_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_OSH_USER FOREIGN KEY(changed_by) REFERENCES sec.APP_USER(user_id));
CREATE INDEX IX_OSH_OP_DATE ON ops.OPERATION_STAGE_HISTORY(operation_id,changed_at DESC);
CREATE TABLE ops.OPERATION_STATUS_HISTORY(operation_status_history_id BIGINT IDENTITY PRIMARY KEY,operation_id BIGINT NOT NULL,status_dimension VARCHAR(20) NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,comment NVARCHAR(1000),changed_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),changed_by BIGINT NOT NULL,CONSTRAINT FK_OSTH_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_OSTH_USER FOREIGN KEY(changed_by) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_OSTH_DIM CHECK(status_dimension IN('OPERATIONAL','DOCUMENTARY','FINANCIAL')));
CREATE TABLE ops.OPERATION_TASK(operation_task_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,workflow_stage_id INT,title NVARCHAR(180) NOT NULL,description NVARCHAR(1000),task_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',priority VARCHAR(10) NOT NULL DEFAULT 'NORMAL',assigned_user_id BIGINT,due_at DATETIME2(0),completed_at DATETIME2(0),completed_by_user_id BIGINT,is_mandatory BIT NOT NULL DEFAULT 0,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_OT_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_OT_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_OT_STAGE FOREIGN KEY(workflow_stage_id) REFERENCES cfg.WORKFLOW_STAGE(workflow_stage_id),CONSTRAINT FK_OT_ASSIGN FOREIGN KEY(assigned_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_OT_COMPLETE FOREIGN KEY(completed_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_OT_STATUS CHECK(task_status IN('PENDING','IN_PROGRESS','BLOCKED','COMPLETED','CANCELLED')),CONSTRAINT CK_OT_PRIORITY CHECK(priority IN('LOW','NORMAL','HIGH','CRITICAL')));
CREATE INDEX IX_OT_ASSIGNEE ON ops.OPERATION_TASK(company_id,assigned_user_id,task_status,due_at);
CREATE TABLE ops.OPERATION_EVENT(operation_event_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,event_type VARCHAR(40) NOT NULL,event_date DATETIME2(0) NOT NULL,title NVARCHAR(180) NOT NULL,description NVARCHAR(1000),source_type VARCHAR(20) NOT NULL DEFAULT 'MANUAL',created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,CONSTRAINT FK_OE_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_OE_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT CK_OE_SOURCE CHECK(source_type IN('MANUAL','SYSTEM','IMPORT')));
CREATE INDEX IX_OE_TIMELINE ON ops.OPERATION_EVENT(operation_id,event_date DESC);
CREATE TABLE ops.SHIPMENT(shipment_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,transport_mode_id INT NOT NULL,carrier_name NVARCHAR(180),vessel_flight_name NVARCHAR(180),booking_no NVARCHAR(100),master_document_no NVARCHAR(100),house_document_no NVARCHAR(100),container_no NVARCHAR(50),seal_no NVARCHAR(50),origin_port_id BIGINT,destination_port_id BIGINT,etd DATETIME2(0),eta DATETIME2(0),actual_departure_at DATETIME2(0),actual_arrival_at DATETIME2(0),shipment_status VARCHAR(30) NOT NULL DEFAULT 'PLANNED',notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_SH_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_SH_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_SH_TRANS FOREIGN KEY(transport_mode_id) REFERENCES cfg.TRANSPORT_MODE(transport_mode_id),CONSTRAINT FK_SH_OPORT FOREIGN KEY(origin_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT FK_SH_DPORT FOREIGN KEY(destination_port_id) REFERENCES cfg.PORT(port_id),CONSTRAINT CK_SH_STATUS CHECK(shipment_status IN('PLANNED','BOOKED','DEPARTED','IN_TRANSIT','ARRIVED','CANCELLED')));
CREATE TABLE ops.CUSTOMS_PROCESS(customs_process_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,customs_regime NVARCHAR(80),declaration_no NVARCHAR(100),declaration_date DATE,customs_office NVARCHAR(150),customs_channel VARCHAR(20),customs_status VARCHAR(30) NOT NULL DEFAULT 'PENDING',duties_amount DECIMAL(19,4),duties_currency_code CHAR(3),release_date DATETIME2(0),observation NVARCHAR(1500),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,row_ver ROWVERSION,
 CONSTRAINT FK_CP_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_CP_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_CP_CURR FOREIGN KEY(duties_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT CK_CP_CHANNEL CHECK(customs_channel IS NULL OR customs_channel IN('GREEN','YELLOW','RED','OTHER')),CONSTRAINT CK_CP_STATUS CHECK(customs_status IN('PENDING','IN_REVIEW','OBSERVED','RELEASED','CANCELLED')));
CREATE TABLE ops.OPERATION_NOTE(operation_note_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,note_type VARCHAR(20) NOT NULL DEFAULT 'INTERNAL',note_text NVARCHAR(2000) NOT NULL,is_pinned BIT NOT NULL DEFAULT 0,created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,CONSTRAINT FK_ON_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_ON_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_ON_USER FOREIGN KEY(created_by) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_ON_TYPE CHECK(note_type IN('INTERNAL','CUSTOMER','INCIDENT')));
GO

CREATE TABLE doc.DOCUMENT(document_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,request_id BIGINT NULL,quotation_id BIGINT NULL,operation_id BIGINT NULL,document_type_id INT NOT NULL,file_name NVARCHAR(260) NOT NULL,original_file_name NVARCHAR(260) NOT NULL,file_extension NVARCHAR(20),mime_type NVARCHAR(150),storage_provider VARCHAR(20) NOT NULL DEFAULT 'LOCAL',storage_key NVARCHAR(600) NOT NULL,file_size_bytes BIGINT,sha256_hash CHAR(64),version_no INT NOT NULL DEFAULT 1,document_status VARCHAR(20) NOT NULL DEFAULT 'VALID',document_date DATE,expiration_date DATE,notes NVARCHAR(1000),uploaded_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),uploaded_by BIGINT NOT NULL,replaced_document_id BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_DOC_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_DOC_REQ FOREIGN KEY(request_id) REFERENCES sales.IMPORT_REQUEST(request_id),CONSTRAINT FK_DOC_QUO FOREIGN KEY(quotation_id) REFERENCES sales.QUOTATION(quotation_id),CONSTRAINT FK_DOC_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_DOC_TYPE FOREIGN KEY(document_type_id) REFERENCES cfg.DOCUMENT_TYPE(document_type_id),CONSTRAINT FK_DOC_USER FOREIGN KEY(uploaded_by) REFERENCES sec.APP_USER(user_id),CONSTRAINT FK_DOC_REPLACED FOREIGN KEY(replaced_document_id) REFERENCES doc.DOCUMENT(document_id),CONSTRAINT CK_DOC_OWNER CHECK((CASE WHEN request_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN quotation_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN operation_id IS NOT NULL THEN 1 ELSE 0 END)=1),CONSTRAINT CK_DOC_STATUS CHECK(document_status IN('VALID','OBSERVED','REPLACED','EXPIRED','VOID')),CONSTRAINT CK_DOC_STORAGE CHECK(storage_provider IN('LOCAL','S3','AZURE_BLOB','MINIO','OTHER')),CONSTRAINT CK_DOC_SIZE CHECK(file_size_bytes IS NULL OR file_size_bytes>=0));
CREATE INDEX IX_DOC_OP ON doc.DOCUMENT(operation_id,document_type_id,uploaded_at DESC) WHERE operation_id IS NOT NULL AND is_deleted=0;
GO

CREATE TABLE fin.OPERATION_BUDGET(operation_budget_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,version_no INT NOT NULL DEFAULT 1,budget_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',base_currency_code CHAR(3) NOT NULL,total_estimated_cost DECIMAL(19,4) NOT NULL DEFAULT 0,total_estimated_service DECIMAL(19,4) NOT NULL DEFAULT 0,total_estimated_amount DECIMAL(19,4) NOT NULL DEFAULT 0,approved_at DATETIME2(0),approved_by_user_id BIGINT,notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,row_ver ROWVERSION,
 CONSTRAINT FK_BUD_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_BUD_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_BUD_CURR FOREIGN KEY(base_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_BUD_APPROVER FOREIGN KEY(approved_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT UQ_BUD_VER UNIQUE(operation_id,version_no),CONSTRAINT CK_BUD_STATUS CHECK(budget_status IN('DRAFT','APPROVED','SUPERSEDED','CANCELLED')));
CREATE TABLE fin.OPERATION_BUDGET_ITEM(operation_budget_item_id BIGINT IDENTITY PRIMARY KEY,operation_budget_id BIGINT NOT NULL,item_type VARCHAR(20) NOT NULL,expense_category_id INT,service_category_id INT,description NVARCHAR(500) NOT NULL,currency_code CHAR(3) NOT NULL,estimated_amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),estimated_base_amount DECIMAL(19,4) NOT NULL,is_rebillable BIT NOT NULL DEFAULT 0,notes NVARCHAR(500),CONSTRAINT FK_BI_BUD FOREIGN KEY(operation_budget_id) REFERENCES fin.OPERATION_BUDGET(operation_budget_id),CONSTRAINT FK_BI_EXP FOREIGN KEY(expense_category_id) REFERENCES cfg.EXPENSE_CATEGORY(expense_category_id),CONSTRAINT FK_BI_SRV FOREIGN KEY(service_category_id) REFERENCES cfg.SERVICE_CATEGORY(service_category_id),CONSTRAINT FK_BI_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT CK_BI_TYPE CHECK(item_type IN('COST','SERVICE')),CONSTRAINT CK_BI_AMT CHECK(estimated_amount>=0 AND estimated_base_amount>=0));
CREATE TABLE fin.CLIENT_FUND(client_fund_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,client_id BIGINT NOT NULL,fund_status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED',fund_nature VARCHAR(20) NOT NULL DEFAULT 'CLIENT_ADVANCE',requested_amount DECIMAL(19,4),received_amount DECIMAL(19,4),currency_code CHAR(3) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4),requested_at DATETIME2(0),received_at DATETIME2(0),payment_method_id INT,reference_no NVARCHAR(120),notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_CF_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_CF_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_CF_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_CF_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_CF_PM FOREIGN KEY(payment_method_id) REFERENCES cfg.PAYMENT_METHOD(payment_method_id),CONSTRAINT CK_CF_STATUS CHECK(fund_status IN('REQUESTED','PARTIAL','RECEIVED','APPLIED','SETTLED','CANCELLED')),CONSTRAINT CK_CF_NATURE CHECK(fund_nature IN('CLIENT_ADVANCE','REIMBURSEMENT','OTHER')));
CREATE TABLE fin.OPERATION_EXPENSE(operation_expense_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,expense_category_id INT NOT NULL,supplier_id BIGINT,expense_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',description NVARCHAR(500) NOT NULL,document_reference NVARCHAR(120),expense_date DATE NOT NULL,due_date DATE,currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,paid_by VARCHAR(20),is_rebillable BIT NOT NULL DEFAULT 1,rebill_amount DECIMAL(19,4),notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_EX_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_EX_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_EX_CAT FOREIGN KEY(expense_category_id) REFERENCES cfg.EXPENSE_CATEGORY(expense_category_id),CONSTRAINT FK_EX_SUP FOREIGN KEY(supplier_id) REFERENCES crm.SUPPLIER(supplier_id),CONSTRAINT FK_EX_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT CK_EX_STATUS CHECK(expense_status IN('PENDING','APPROVED','PARTIALLY_PAID','PAID','CANCELLED')),CONSTRAINT CK_EX_PAIDBY CHECK(paid_by IS NULL OR paid_by IN('COMPANY','CLIENT','THIRD_PARTY')),CONSTRAINT CK_EX_AMT CHECK(amount>=0 AND base_amount>=0 AND(rebill_amount IS NULL OR rebill_amount>=0)));
CREATE INDEX IX_EX_OP_STATUS ON fin.OPERATION_EXPENSE(operation_id,expense_status,expense_date DESC);
CREATE TABLE fin.EXPENSE_PAYMENT(expense_payment_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_expense_id BIGINT NOT NULL,payment_date DATETIME2(0) NOT NULL,currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,payer_type VARCHAR(20) NOT NULL,payment_method_id INT,reference_no NVARCHAR(120),notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,is_void BIT NOT NULL DEFAULT 0,voided_at DATETIME2(0),voided_by BIGINT,void_reason NVARCHAR(500),row_ver ROWVERSION,
 CONSTRAINT FK_EP_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_EP_EXP FOREIGN KEY(operation_expense_id) REFERENCES fin.OPERATION_EXPENSE(operation_expense_id),CONSTRAINT FK_EP_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_EP_PM FOREIGN KEY(payment_method_id) REFERENCES cfg.PAYMENT_METHOD(payment_method_id),CONSTRAINT FK_EP_VOIDBY FOREIGN KEY(voided_by) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_EP_PAYER CHECK(payer_type IN('COMPANY','CLIENT','THIRD_PARTY')),CONSTRAINT CK_EP_AMT CHECK(amount>0 AND base_amount>0));
CREATE TABLE fin.OPERATION_SERVICE(operation_service_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,service_category_id INT NOT NULL,service_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',description NVARCHAR(500) NOT NULL,currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,service_date DATE,due_date DATE,notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,is_deleted BIT NOT NULL DEFAULT 0,row_ver ROWVERSION,
 CONSTRAINT FK_OS_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_OS_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_OS_CAT FOREIGN KEY(service_category_id) REFERENCES cfg.SERVICE_CATEGORY(service_category_id),CONSTRAINT FK_OS_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT CK_OS_STATUS CHECK(service_status IN('PENDING','PARTIALLY_COLLECTED','COLLECTED','CANCELLED')),CONSTRAINT CK_OS_AMT CHECK(amount>=0 AND base_amount>=0));
CREATE TABLE fin.CLIENT_COLLECTION(client_collection_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,client_id BIGINT NOT NULL,collection_type VARCHAR(20) NOT NULL,collection_status VARCHAR(20) NOT NULL DEFAULT 'RECEIVED',collection_date DATETIME2(0) NOT NULL,currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,payment_method_id INT,reference_no NVARCHAR(120),notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,is_void BIT NOT NULL DEFAULT 0,voided_at DATETIME2(0),voided_by BIGINT,void_reason NVARCHAR(500),row_ver ROWVERSION,
 CONSTRAINT FK_CC_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_CC_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_CC_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_CC_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_CC_PM FOREIGN KEY(payment_method_id) REFERENCES cfg.PAYMENT_METHOD(payment_method_id),CONSTRAINT FK_CC_VOIDBY FOREIGN KEY(voided_by) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_CC_TYPE CHECK(collection_type IN('SERVICE','FUND','OTHER')),CONSTRAINT CK_CC_STATUS CHECK(collection_status IN('RECEIVED','APPLIED','VOID')),CONSTRAINT CK_CC_AMT CHECK(amount>0 AND base_amount>0));
CREATE TABLE fin.SERVICE_COLLECTION_ALLOCATION(service_collection_allocation_id BIGINT IDENTITY PRIMARY KEY,operation_service_id BIGINT NOT NULL,client_collection_id BIGINT NOT NULL,allocated_amount DECIMAL(19,4) NOT NULL,allocated_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,CONSTRAINT FK_SCA_SERVICE FOREIGN KEY(operation_service_id) REFERENCES fin.OPERATION_SERVICE(operation_service_id),CONSTRAINT FK_SCA_COLLECTION FOREIGN KEY(client_collection_id) REFERENCES fin.CLIENT_COLLECTION(client_collection_id),CONSTRAINT UQ_SCA UNIQUE(operation_service_id,client_collection_id),CONSTRAINT CK_SCA_AMT CHECK(allocated_amount>0));
CREATE TABLE fin.OPERATION_ADJUSTMENT(operation_adjustment_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,adjustment_type VARCHAR(20) NOT NULL,reason NVARCHAR(500) NOT NULL,currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,adjustment_date DATE NOT NULL,notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,is_void BIT NOT NULL DEFAULT 0,CONSTRAINT FK_OA_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_OA_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_OA_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT CK_OA_TYPE CHECK(adjustment_type IN('DEBIT','CREDIT','CORRECTION')),CONSTRAINT CK_OA_AMT CHECK(amount>0 AND base_amount>0));
CREATE TABLE fin.CLIENT_REFUND(client_refund_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,client_id BIGINT NOT NULL,refund_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',refund_date DATETIME2(0),currency_code CHAR(3) NOT NULL,amount DECIMAL(19,4) NOT NULL,exchange_rate DECIMAL(18,8),base_amount DECIMAL(19,4) NOT NULL,payment_method_id INT,reference_no NVARCHAR(120),reason NVARCHAR(500),notes NVARCHAR(1000),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,row_ver ROWVERSION,
 CONSTRAINT FK_CR_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_CR_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_CR_CLIENT FOREIGN KEY(client_id) REFERENCES crm.CLIENT(client_id),CONSTRAINT FK_CR_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_CR_PM FOREIGN KEY(payment_method_id) REFERENCES cfg.PAYMENT_METHOD(payment_method_id),CONSTRAINT CK_CR_STATUS CHECK(refund_status IN('PENDING','COMPLETED','CANCELLED')),CONSTRAINT CK_CR_AMT CHECK(amount>0 AND base_amount>0));
CREATE TABLE fin.OPERATION_SETTLEMENT(operation_settlement_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,settlement_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',base_currency_code CHAR(3) NOT NULL,total_client_funds DECIMAL(19,4) NOT NULL DEFAULT 0,total_expenses DECIMAL(19,4) NOT NULL DEFAULT 0,total_company_services DECIMAL(19,4) NOT NULL DEFAULT 0,total_collections DECIMAL(19,4) NOT NULL DEFAULT 0,total_refunds DECIMAL(19,4) NOT NULL DEFAULT 0,total_adjustments DECIMAL(19,4) NOT NULL DEFAULT 0,client_balance DECIMAL(19,4) NOT NULL DEFAULT 0,settlement_date DATETIME2(0),approved_at DATETIME2(0),approved_by_user_id BIGINT,notes NVARCHAR(1500),created_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),created_by BIGINT NOT NULL,modified_at DATETIME2(0),modified_by BIGINT,row_ver ROWVERSION,
 CONSTRAINT FK_SETT_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_SETT_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),CONSTRAINT FK_SETT_CURR FOREIGN KEY(base_currency_code) REFERENCES cfg.CURRENCY(currency_code),CONSTRAINT FK_SETT_APPROVER FOREIGN KEY(approved_by_user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT UQ_SETT_OP UNIQUE(operation_id),CONSTRAINT CK_SETT_STATUS CHECK(settlement_status IN('DRAFT','PENDING_APPROVAL','APPROVED','CANCELLED')));
GO

CREATE TABLE audit.AUDIT_LOG(audit_log_id BIGINT IDENTITY PRIMARY KEY,company_id BIGINT NULL,user_id BIGINT NULL,event_at DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),entity_name NVARCHAR(128) NOT NULL,entity_id NVARCHAR(100),action_type VARCHAR(20) NOT NULL,old_values_json NVARCHAR(MAX),new_values_json NVARCHAR(MAX),ip_address NVARCHAR(64),user_agent NVARCHAR(500),correlation_id UNIQUEIDENTIFIER,
 CONSTRAINT FK_AL_COMPANY FOREIGN KEY(company_id) REFERENCES cfg.COMPANY(company_id),CONSTRAINT FK_AL_USER FOREIGN KEY(user_id) REFERENCES sec.APP_USER(user_id),CONSTRAINT CK_AL_ACTION CHECK(action_type IN('INSERT','UPDATE','DELETE','LOGIN','LOGOUT','DOWNLOAD','STATUS_CHANGE','OTHER')),CONSTRAINT CK_AL_OLDJSON CHECK(old_values_json IS NULL OR ISJSON(old_values_json)=1),CONSTRAINT CK_AL_NEWJSON CHECK(new_values_json IS NULL OR ISJSON(new_values_json)=1));
CREATE INDEX IX_AL_COMPANY_DATE ON audit.AUDIT_LOG(company_id,event_at DESC);
GO

CREATE VIEW fin.VW_OPERATION_FINANCIAL_SUMMARY AS
SELECT o.operation_id,o.company_id,o.operation_no,o.client_id,
 ISNULL(f.total_client_funds,0) total_client_funds,ISNULL(e.total_expenses,0) total_expenses,ISNULL(ep.total_expense_payments,0) total_expense_payments,
 ISNULL(s.total_services,0) total_services,ISNULL(c.total_collections,0) total_collections,ISNULL(r.total_refunds,0) total_refunds,
 ISNULL(f.total_client_funds,0)-ISNULL(ep.company_paid_expenses,0)-ISNULL(r.total_refunds,0) managed_fund_balance,
 CASE WHEN ISNULL(s.total_services,0)-ISNULL(c.service_collections,0)<0 THEN 0 ELSE ISNULL(s.total_services,0)-ISNULL(c.service_collections,0) END pending_service_collection
FROM ops.IMPORT_OPERATION o
OUTER APPLY(SELECT SUM(ISNULL(base_amount,received_amount)) total_client_funds FROM fin.CLIENT_FUND x WHERE x.operation_id=o.operation_id AND x.is_deleted=0 AND x.fund_status IN('PARTIAL','RECEIVED','APPLIED','SETTLED'))f
OUTER APPLY(SELECT SUM(base_amount) total_expenses FROM fin.OPERATION_EXPENSE x WHERE x.operation_id=o.operation_id AND x.is_deleted=0 AND x.expense_status<>'CANCELLED')e
OUTER APPLY(SELECT SUM(p.base_amount) total_expense_payments,SUM(CASE WHEN p.payer_type='COMPANY' THEN p.base_amount ELSE 0 END) company_paid_expenses FROM fin.EXPENSE_PAYMENT p JOIN fin.OPERATION_EXPENSE ex ON ex.operation_expense_id=p.operation_expense_id WHERE ex.operation_id=o.operation_id AND p.is_void=0)ep
OUTER APPLY(SELECT SUM(base_amount) total_services FROM fin.OPERATION_SERVICE x WHERE x.operation_id=o.operation_id AND x.is_deleted=0 AND x.service_status<>'CANCELLED')s
OUTER APPLY(SELECT SUM(base_amount) total_collections,SUM(CASE WHEN collection_type='SERVICE' THEN base_amount ELSE 0 END) service_collections FROM fin.CLIENT_COLLECTION x WHERE x.operation_id=o.operation_id AND x.is_void=0 AND x.collection_status<>'VOID')c
OUTER APPLY(SELECT SUM(base_amount) total_refunds FROM fin.CLIENT_REFUND x WHERE x.operation_id=o.operation_id AND x.refund_status='COMPLETED')r
WHERE o.is_deleted=0;
GO

CREATE VIEW ops.VW_OPERATION_DASHBOARD AS
SELECT o.operation_id,o.company_id,o.operation_no,o.client_id,c.legal_name client_name,o.responsible_user_id,CONCAT(ISNULL(u.first_name,''),' ',ISNULL(u.last_name,'')) responsible_name,o.current_stage_id,ws.name current_stage_name,o.operational_status,o.documentary_status,o.financial_status,o.opened_at,o.estimated_close_date,o.actual_close_date,s.eta,s.shipment_status,cp.customs_status
FROM ops.IMPORT_OPERATION o JOIN crm.CLIENT c ON c.client_id=o.client_id JOIN sec.APP_USER u ON u.user_id=o.responsible_user_id JOIN cfg.WORKFLOW_STAGE ws ON ws.workflow_stage_id=o.current_stage_id
OUTER APPLY(SELECT TOP 1 sh.eta,sh.shipment_status FROM ops.SHIPMENT sh WHERE sh.operation_id=o.operation_id AND sh.is_deleted=0 ORDER BY sh.created_at DESC)s
OUTER APPLY(SELECT TOP 1 cu.customs_status FROM ops.CUSTOMS_PROCESS cu WHERE cu.operation_id=o.operation_id ORDER BY cu.customs_process_id DESC)cp
WHERE o.is_deleted=0;
GO

