/* ============================================================================
   15. EXTENSIONES DE ROBUSTEZ V1
============================================================================ */

CREATE TABLE sec.PERMISSION(
 permission_id INT IDENTITY PRIMARY KEY,
 code VARCHAR(80) NOT NULL UNIQUE,
 name NVARCHAR(120) NOT NULL,
 module_code VARCHAR(40) NOT NULL,
 is_active BIT NOT NULL DEFAULT 1
);
CREATE TABLE sec.ROLE_PERMISSION(
 role_id INT NOT NULL,
 permission_id INT NOT NULL,
 can_view BIT NOT NULL DEFAULT 1,
 can_create BIT NOT NULL DEFAULT 0,
 can_update BIT NOT NULL DEFAULT 0,
 can_delete BIT NOT NULL DEFAULT 0,
 can_approve BIT NOT NULL DEFAULT 0,
 PRIMARY KEY(role_id,permission_id),
 CONSTRAINT FK_RP_ROLE FOREIGN KEY(role_id) REFERENCES sec.ROLE(role_id),
 CONSTRAINT FK_RP_PERMISSION FOREIGN KEY(permission_id) REFERENCES sec.PERMISSION(permission_id)
);
GO

CREATE TABLE ops.OPERATION_CARGO_ITEM(
 operation_cargo_item_id BIGINT IDENTITY PRIMARY KEY,
 operation_id BIGINT NOT NULL,
 line_no INT NOT NULL,
 description NVARCHAR(500) NOT NULL,
 hs_code NVARCHAR(30) NULL,
 quantity DECIMAL(18,4) NULL,
 unit_of_measure NVARCHAR(30) NULL,
 gross_weight_kg DECIMAL(18,3) NULL,
 net_weight_kg DECIMAL(18,3) NULL,
 volume_m3 DECIMAL(18,4) NULL,
 declared_value DECIMAL(19,4) NULL,
 currency_code CHAR(3) NULL,
 origin_country_code CHAR(2) NULL,
 notes NVARCHAR(500) NULL,
 CONSTRAINT FK_CARGO_OP FOREIGN KEY(operation_id) REFERENCES ops.IMPORT_OPERATION(operation_id),
 CONSTRAINT FK_CARGO_CURR FOREIGN KEY(currency_code) REFERENCES cfg.CURRENCY(currency_code),
 CONSTRAINT FK_CARGO_COUNTRY FOREIGN KEY(origin_country_code) REFERENCES cfg.COUNTRY(country_code),
 CONSTRAINT UQ_CARGO_LINE UNIQUE(operation_id,line_no)
);
GO

CREATE TABLE ops.SHIPMENT_CONTAINER(
 shipment_container_id BIGINT IDENTITY PRIMARY KEY,
 shipment_id BIGINT NOT NULL,
 container_no NVARCHAR(50) NOT NULL,
 container_type NVARCHAR(30) NULL,
 seal_no NVARCHAR(50) NULL,
 package_count DECIMAL(18,3) NULL,
 gross_weight_kg DECIMAL(18,3) NULL,
 notes NVARCHAR(500) NULL,
 CONSTRAINT FK_CONTAINER_SHIPMENT FOREIGN KEY(shipment_id) REFERENCES ops.SHIPMENT(shipment_id),
 CONSTRAINT UQ_CONTAINER_SHIPMENT UNIQUE(shipment_id,container_no)
);
GO

